function bookTopicId(id,book){
 const mapped=SEED.topicAliases?.[id]||id;
 const target=SEED.sections.find(t=>t.id===mapped&&!t.archived&&t.book===book);
 if(target)return target.id;
 const legacy=SEED.sectionBookMap?.[id]?.[String(book)];
 const next=SEED.topicAliases?.[legacy]||legacy;
 if(SEED.sections.some(t=>t.id===next&&!t.archived&&t.book===book))return next;
 return `sm${book}-personal`;
}
function normalizeBookEntry(e){
 const c=SEED.chapters.find(c=>c.id===e.chapter),book=c?.book||(+e.book===2?2:1);
 let sid=bookTopicId(e.section,book),t=SEED.sections.find(t=>t.id===sid);
 if(c&&t?.chapter!==c.id)sid=SEED.sections.find(t=>!t.archived&&t.chapter===c.id)?.id||sid;
 return {...e,book,section:sid};
}
function applyCategoryRevision(){
 if((state.categoryRevision||0)>=SEED.categoryRevision)return;
 for(const [id,override] of Object.entries(state.overrides)){
  const seed=SEED.entries.find(e=>e.id===id),old=SEED.entryPlacementMigration?.[id];
  if(seed&&old&&(+override.book||old.book)===old.book&&(override.chapter||null)===(old.chapter||null)){
   const oldTopic=override.section===old.section||SEED.topicAliases?.[override.section]===seed.section||(!old.chapter&&!override.chapter);
   if(oldTopic){
    for(const field of ['book','chapter','section','placement','sourcePlacement','sourcePage','sourceForm']){
     if(seed[field]!==undefined)override[field]=seed[field];else delete override[field];
    }
    delete override.classificationNote;
   }
  }
  Object.assign(override,normalizeBookEntry(override));
 }
 state.custom=state.custom.map(normalizeBookEntry);
 state.categoryRevision=SEED.categoryRevision;
}
