function combinedEntries(list){const groups=new Map();for(const e of list){const id=`${e.book}|${e.chapter||e.section}|${e.fi.normalize('NFC').trim().toLocaleLowerCase('fi')}`;if(!groups.has(id)){groups.set(id,{...e});continue}const first=groups.get(id),senses=[...(first.senses||[{fi:first.fi,pos:first.pos,en:first.en}]),...(e.senses||[{fi:e.fi,pos:e.pos,en:e.en}])];first.senses=[...new Map(senses.map(s=>[JSON.stringify(s),s])).values()];first.pos=[...new Set(first.senses.flatMap(s=>s.pos.split('+')))].join('+');first.en=first.senses.map(s=>s.en+' ('+posLabel(s.pos).toLowerCase()+')').join('; ');}return [...groups.values()]}
const sourceIds=id=>[id,...Object.entries(SEED.entryAliases||{}).filter(([,next])=>next===id).map(([old])=>old)];
const isStarred=id=>sourceIds(id).some(x=>state.stars.includes(x));
const entries=()=>combinedEntries([...SEED.entries.map(e=>{const overrides=sourceIds(e.id).map(id=>state.overrides[id]).filter(Boolean);if(!overrides.length)return e;const override={...overrides[0]};if((SEED.legacyProgressKeys?.[e.id]||[]).includes(key(override))&&key(override)!==key(e)){for(const field of ['fi','en','pos','senses'])delete override[field]}const result={...e,...override,id:e.id};if(override.en&&override.en!==e.en&&!override.senses)delete result.senses;return result}),...state.custom].map(normalizeBookEntry).filter(e=>!sourceIds(e.id).some(id=>state.hidden.includes(id))));
const key=e=>`${e.fi.normalize('NFC')}|${e.pos}|${e.en}`;
const prog=e=>{if(state.progress[key(e)])return state.progress[key(e)];const prior=(SEED.legacyProgressKeys?.[e.id]||[]).map(k=>state.progress[k]).filter(Boolean);return prior.length?prior.reduce((a,b)=>({level:Math.max(a.level,b.level),seen:Math.max(a.seen,b.seen),right:Math.max(a.right,b.right),last:Math.max(a.last||0,b.last||0)})):{level:0,seen:0,right:0}};
