function normalize(v){return v.normalize('NFC').toLowerCase().trim().replace(/[.!?,:]+$/g,'').replace(/[’‘]/g,"'").replace(/\s+/g,' ')}
function accepted(given,e,listen=false){let target=listen?e.fi:answer(e),g=normalize(given);if(listen||session.direction==='en-fi'){let t=normalize(target);if(!state.settings.strict){g=g.replace(/[äå]/g,'a').replace(/ö/g,'o');t=t.replace(/[äå]/g,'a').replace(/ö/g,'o')}return g===t}let candidates=(e.senses?e.senses.map(s=>s.en).join(';'):target).split(';').flatMap(x=>[x,x.replace(/\([^)]*\)/g,'')]).map(normalize);return candidates.some(x=>g===x||g===x.replace(/^to /,'')||g.replace(/^to /,'')===x)}
function submitAnswer(given){let s=session;if(s.feedback)return;let e=s.words[s.index];let ok=s.mode==='learn'?given===answer(e):accepted(given,e,s.mode==='listen');s.feedback={ok,given};renderSession()}
function nextQuestion(){let s=session,e=s.words[s.index],ok=s.feedback.ok;record(e,ok?1:0);s.attempts++;if(ok)s.correct++;else{s.misses.push(e);if(s.mode==='learn'&&(s.retryCounts[e.id]||0)<2){s.retryCounts[e.id]=(s.retryCounts[e.id]||0)+1;s.words.push(e)}}s.index++;s.feedback=null;s.options=null;if(s.index>=s.words.length)s.complete=true;window.scrollTo(0,0);renderSession()}
function finnishVoice(){return typeof speechSynthesis!=='undefined'?speechSynthesis.getVoices().find(v=>/^fi[-_]?/i.test(v.lang)):null}
function speak(text){if(typeof speechSynthesis==='undefined'){toast('Speech isn’t supported in this browser.');return}let v=finnishVoice();if(!v){toast('No Finnish voice found. Add a Finnish text-to-speech voice in your device settings.');return}speechSynthesis.cancel();let u=new SpeechSynthesisUtterance(text);u.lang='fi-FI';u.voice=v;u.rate=.85;u.onerror=()=>toast('Audio could not play. Check your device’s speech settings.');speechSynthesis.speak(u)}
if(typeof speechSynthesis!=='undefined')speechSynthesis.getVoices();
function makeBoard(){let s=session;s.board=s.words.slice(s.round*6,s.round*6+6);s.left=shuffle(s.board);s.right=shuffle(s.board);s.matched=[];s.selection=null}
function renderMatch(){let s=session;shell(`<div class="studywrap"><div class="row spread studyhead"><button class="ghost" id="quit">${icon('close')} End session</button><span class="chip">Match · board ${s.round+1} / ${Math.ceil(s.words.length/6)}</span><small>${s.attempts} attempts</small></div><h2 style="margin:30px 0 10px">A word. Its other half.</h2><p class="muted">Choose one Finnish word and its English meaning.</p><div class="matchgrid"><div class="matchcol">${s.left.map(e=>matchTile(e,'fi')).join('')}</div><div class="matchcol">${s.right.map(e=>matchTile(e,'en')).join('')}</div></div><p id="matchFeedback" role="status" class="muted" style="text-align:center;min-height:25px">${s.matchMessage||''}</p><div class="studyactions">${s.matched.length===s.board.length?'<button class="primary" id="nextBoard">'+((s.round+1)*6>=s.words.length?'See results':'Next board')+' →</button>':''}</div><p class="keyboard">Matching counts toward your daily practice goal. Recall modes build mastery.</p></div>`);$('#quit').onclick=()=>confirmDialog('End matching?','Only signed-in practice is saved.',()=>{session=null;view='practice';render()});$$('[data-match]').forEach(b=>b.onclick=()=>selectMatch(b.dataset.match,b.dataset.side));if($('#nextBoard'))$('#nextBoard').onclick=()=>{s.round++;if(s.round*6>=s.words.length){s.complete=true;renderSession()}else{makeBoard();s.matchMessage='';renderMatch()}}}
function matchTile(e,side){let s=session;return `<button class="matchtile ${s.matched.includes(e.id)?'matched':''} ${s.selection?.id===e.id&&s.selection?.side===side?'selected':''}" data-match="${e.id}" data-side="${side}" ${s.matched.includes(e.id)?'disabled':''}>${esc(e[side])}</button>`}
function selectMatch(id,side){let s=session;if(!s.selection||s.selection.side===side){s.selection={id,side};renderMatch();return}s.attempts++;let first=s.board.find(e=>e.id===s.selection.id),second=s.board.find(e=>e.id===id);if(first.id===second.id||first.fi===second.fi&&first.en===second.en){s.matched.push(first.id,second.id);s.matched=[...new Set(s.matched)];s.correct++;if(account.user){let h=state.history[day()]||{reviews:0,right:0};h.reviews++;h.right++;state.history[day()]=h;save();}s.matchMessage='✓ A perfect pair.'}else{s.matchMessage='Not a pair yet. Try another connection.'}s.selection=null;renderMatch()}
function renderTest(){let s=session;shell(`<div class="studywrap"><div class="row spread"><button class="ghost" id="quit">${icon('close')} End test</button><span class="chip">${s.words.length} questions · ${s.direction==='en-fi'?'English → Finnish':'Finnish → English'}</span></div><h2 style="margin:28px 0 12px">Let’s see what stayed with you.</h2><p class="muted">Take your time. Your answers are marked when you finish.</p><form id="testForm" class="panel" style="padding:0">${s.words.map((e,i)=>`<div class="testitem"><small>QUESTION ${i+1} · ${esc(posLabel(e.pos))}</small><h3 style="margin-top:12px">${esc(prompt(e))}</h3><input name="q${i}" aria-label="Answer to question ${i+1}" autocomplete="off" spellcheck="false" value="${esc(s.testAnswers[i]||'')}" placeholder="Your answer…"></div>`).join('')}<div style="padding:24px"><button class="primary">Finish and check answers →</button></div></form></div>`);$('#quit').onclick=()=>confirmDialog('Leave this test?','Unsubmitted test answers will be discarded.',()=>{session=null;view='practice';render()});$$('#testForm input').forEach((inp,i)=>inp.oninput=()=>s.testAnswers[i]=inp.value);$('#testForm').onsubmit=ev=>{ev.preventDefault();s.results=s.words.map((e,i)=>({e,given:s.testAnswers[i]||'',ok:accepted(s.testAnswers[i]||'',e)}));s.results.forEach(r=>record(r.e,r.ok?1:0));s.attempts=s.words.length;s.correct=s.results.filter(r=>r.ok).length;s.misses=s.results.filter(r=>!r.ok).map(r=>r.e);s.complete=true;renderSession()}}
function sessionSummary(){window.scrollTo(0,0);if(session.mode==='flash'){flashSummary();return}let s=session,score=s.attempts?Math.round(s.correct/s.attempts*100):0;shell(`<div class="studywrap"><div class="panel summary"><span class="chip">SESSION COMPLETE</span><div class="bigscore">${score}<span style="font-size:32px">%</span></div><h2>${score>=80?'Look at you, learning Finnish.':'Every attempt is a step forward.'}</h2><p class="muted">${s.correct} of ${s.attempts} ${s.mode==='flash'?'cards recalled':s.mode==='match'?'pair attempts correct':'answers correct'}</p><div class="row wrap"><button class="primary" id="finishSession">Back to overview</button>${s.misses.length?'<button id="retryMissed">Practice missed words</button>':''}<button id="repeatSession">Practice again</button></div></div>${s.results.length?`<div class="panel"><h3 style="margin-bottom:20px">Your test, reviewed</h3>${s.results.map((r,i)=>`<div class="feedback ${r.ok?'correct':'wrong'}"><strong>${esc(r.e.fi)}</strong> — ${esc(r.e.en)}<br><small>Your answer: ${esc(r.given)||'(blank)'}</small>${!r.ok?`<br><button style="margin-top:9px" data-testcorrect="${i}">My answer was also correct</button>`:''}</div>`).join('')}</div>`:''}${s.misses.length&&!s.results.length?`<div class="panel"><h3>Words to revisit</h3><p class="muted">${unique(s.misses).map(e=>esc(e.fi)).join(' · ')}</p></div>`:''}</div>`);$('#finishSession').onclick=()=>{session=null;view='home';render()};$('#repeatSession').onclick=()=>startSession(s.mode,shuffle(unique(s.words)),s.direction,s.pool);if($('#retryMissed'))$('#retryMissed').onclick=()=>startSession('learn',shuffle(unique(s.misses)),s.direction,s.pool);$$('[data-testcorrect]').forEach(b=>b.onclick=()=>{let r=s.results[+b.dataset.testcorrect];if(r.ok)return;r.ok=true;s.correct++;s.misses=s.results.filter(x=>!x.ok).map(x=>x.e);if(account.user){let p=prog(r.e);state.progress[key(r.e)]={...p,level:1,right:p.right+1};state.history[day()].right++;save();}sessionSummary()})}
function progressView(){if(!account.user){guestAccountPage('Your progress, saved for you.');return}let a=unique(entries()),p=a.filter(e=>prog(e).seen),rights=Object.values(state.history).reduce((n,h)=>n+h.right,0),reviews=Object.values(state.history).reduce((n,h)=>n+h.reviews,0);let dates=Array.from({length:84},(_,i)=>{let d=new Date();d.setDate(d.getDate()-(83-i));return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`});shell(`${heading('SMALL STEPS ADD UP','Your Finnish is growing.','A clear picture of your practice, without the pressure.')}<div class="stats">${[['Words studied',p.length,'Distinct Finnish + meaning entries'],['Words mastered',a.filter(mastered).length,'Four successful recalls in a row'],['Practice accuracy',reviews?Math.round(rights/reviews*100)+'%':'—','Across rated practice answers'],['Current streak',streak()+' days','A little practice every day']].map(([t,n,s])=>`<div class="stat"><small>${t}</small><strong>${n}</strong><small>${s}</small></div>`).join('')}</div><div class="panel"><div class="row spread"><h3>A rhythm of your own</h3><small>Last 84 days</small></div><div class="heatmap">${dates.map(d=>`<i title="${d}: ${state.history[d]?.reviews||0} answers" style="background:${(state.history[d]?.reviews||0)>=state.settings.goal?'var(--activity-goal)':state.history[d]?.reviews?'var(--activity-some)':'var(--activity-empty)'}"></i>`).join('')}</div><small>Light green: some practice · Dark green: daily goal reached</small><div style="margin-top:14px"><button id="activityDetails">View daily activity</button></div></div><div class="panel"><h3>Chapter by chapter</h3>${SEED.chapters.map(c=>{let arr=entries().filter(e=>e.chapter===c.id);return `<div style="margin-top:22px"><div class="row spread"><span style="font-size:13px">SM${c.book} · ${c.number}. ${esc(titleFi(c.title))}</span><small>${arr.filter(mastered).length} / ${arr.length}</small></div><div class="progressbar"><i style="width:${pct(arr)}%"></i></div></div>`}).join('')}</div><div class="panel"><h3>How progress works</h3><p class="muted" style="font-size:13px">Remembered or correct answers build a word’s recall progress. Four successful recalls in a row mark it as mastered. Still learning or an incorrect answer starts that word’s recall progress over. Skip leaves progress unchanged. You choose when to practice; there are no scheduled reviews. Identical Finnish words with the same part of speech and English definition share progress across chapters. Matching builds familiarity and daily practice, but does not raise mastery.</p></div>`);$('#activityDetails').onclick=()=>{let m=$('#modal');m.innerHTML=`<h2>Your daily practice</h2><p class="muted">Your last 84 days, most recent first.</p><div class="activitylist">${dates.reverse().map(d=>`<div class="row spread"><span>${d}</span><strong>${state.history[d]?.reviews||0} answers</strong></div>`).join('')}</div><div class="actions"><button id="closeActivity" class="primary">Done</button></div>`;$('#closeActivity').onclick=()=>m.close();m.showModal()}}
function confirmDialog(title,text,fn){let m=$('#modal');m.innerHTML=`<h2>${esc(title)}</h2><p class="muted">${esc(text)}</p><div class="actions"><button id="no">Cancel</button><button id="yes" class="primary">Continue</button></div>`;$('#no').onclick=()=>m.close();$('#yes').onclick=()=>{m.close();fn()};m.showModal()}
function removedWordsPanel(){
 if(!canEditVocabulary())return '';
 const removed=SEED.entries.filter(e=>sourceIds(e.id).some(id=>state.hidden.includes(id)));
 return `<section class="panel"><h3>Removed words</h3><p class="muted">Restore individual words from the original collection. This keeps your progress, stars and other edits.</p>${removed.length?removed.map(e=>`<div class="row spread" style="gap:16px;flex-wrap:wrap;padding:12px 0;border-top:1px solid var(--line)"><div><strong lang="fi">${esc(e.fi)}</strong> — ${esc(e.en)}<br><small>SM${e.book} · Chapter ${chapter(e.chapter)?.number||''} · ${esc(section(e.section)?.title||'Vocabulary')}</small></div><button data-restore-word="${esc(e.id)}">Restore word</button></div>`).join(''):'<p class="sourceinfo">No original words are currently removed.</p>'}</section>`;
}
function restoreRemovedWord(id){
 if(!canEditVocabulary()){toast('Only Sawyer can restore vocabulary.');return false}
 const canonical=SEED.entryAliases?.[id]||id,word=SEED.entries.find(e=>e.id===canonical);if(!word)return false;
 const ids=sourceIds(canonical);state.hidden=state.hidden.filter(hidden=>!ids.includes(hidden));save();render();toast(`Restored ${word.fi} — ${word.en}.`);return true;
}
function restoredAccountState(incoming){return canEditVocabulary()?incoming:{...incoming,overrides:state.overrides,custom:state.custom,hidden:state.hidden}}
function manage(){if(!account.user){guestAccountPage('Your personal vocabulary studio.');return}shell(`${heading('MAKE IT YOURS','A studio that grows with you.',canEditVocabulary()?'Edit your vocabulary, bring in new words, and keep your progress safe.':'Manage your preferences and progress. Vocabulary editing is reserved for Sawyer.')}${removedWordsPanel()}<div class="settingsgrid"><section class="panel"><h3>Learning preferences</h3><label class="appearance-control">Appearance<select id="appearance" aria-label="Appearance"><option value="system">System · follow device</option><option value="light">Light</option><option value="dark">Dark</option></select></label><small class="appearance-note">Applies immediately and stays saved on this device.</small><form id="preferences" style="margin-top:20px"><div class="formgrid"><label>Daily practice goal<input name="goal" type="number" min="1" max="500" value="${state.settings.goal}" required></label><p class="sourceinfo">Sessions start with the entire selected chapter or topic. Choose a smaller batch in study setup if you want one.</p><p class="sourceinfo full">Study sessions start Finnish → English. You can reverse the direction for an individual session.</p><label class="check full"><input type="checkbox" name="strict" ${state.settings.strict?'checked':''}> Require ä, ö and å in Finnish answers</label></div><p class="sourceinfo">Capitalization and extra spaces are ignored. Finnish long vowels and double consonants are always significant.</p><button class="primary">Save preferences</button></form></section><section class="panel"><h3>Your vocabulary</h3><p class="muted" style="font-size:13px">${canEditVocabulary()?'Add a word by hand or import a collection. Imports are previewed before anything changes.':'Vocabulary is read-only. Only Sawyer can add, edit, import or remove words.'}</p><div class="row wrap"><button id="addWord">+ Add word</button><button id="importWords">Import CSV / JSON</button></div><p class="sourceinfo">CSV columns: fi, en, pos, book, chapter, section, spoken, notes. Only fi and en are required. JSON accepts an array of entries or a vocabulary export.</p><div class="row wrap"><button class="ghost" id="downloadCSV">Export vocabulary CSV ↓</button><button class="ghost" id="downloadJSON">Export vocabulary JSON ↓</button></div><button class="ghost" id="templateCSV">Download import template ↓</button></section><section class="panel"><h3>Keep your progress safe</h3><p class="muted" style="font-size:13px">Your progress and edits are saved to your signed-in account and available on your other devices. A full backup includes your vocabulary, stars, settings and learning history.</p><div class="row wrap"><button class="primary" id="backup">Download full backup</button><button id="restore">Restore backup</button><button id="importLegacy">Import previous device progress</button></div><p class="sourceinfo">Sign in with the same username on another device to continue. Keep a downloaded backup as an extra copy.</p></section><section class="panel"><h3>About this collection</h3><p class="muted" style="font-size:13px">${SEED.entries.length.toLocaleString('en-US')} vocabulary entries · 17 chapters · 111 original source sections, with categorized topics organized within each book. Imported from your revised Finnish–English document.</p><p class="sourceinfo">${esc(SEED.sourceNotes)}</p><p class="sourceinfo">App version: ${esc(document.querySelector('meta[name="sisu-build"]')?.content||'standalone')}</p><p class="sourceinfo">Printed book opening pages: SM1 ${SEED.chapters.filter(c=>c.book===1).map(c=>c.page).join(', ')}. SM2 ${SEED.chapters.filter(c=>c.book===2).map(c=>c.page).join(', ')}. These refer to the printed book, not the PDF viewer.</p><button id="voiceTest">${icon('sound')} Test Finnish pronunciation</button><p class="sourceinfo" id="voiceInfo">${finnishVoice()?'Finnish voice available: '+esc(finnishVoice().name):'No Finnish voice currently detected. Add a Finnish text-to-speech voice to your device for pronunciation and listening.'}</p></section></div><section class="panel"><h3>Start fresh</h3><p class="muted" style="font-size:13px">Reset learning progress while keeping your vocabulary, edits and starred words. Download a backup first if you may want to recover your history.</p><button class="danger" id="resetProgress">Reset learning progress</button></section><input type="file" id="fileInput" accept=".csv,.json" class="hidden"><input type="file" id="backupInput" accept=".json" class="hidden">`);$('#appearance').value=themePreference;$('#appearance').onchange=e=>setTheme(e.target.value);$('#preferences').onsubmit=e=>{e.preventDefault();let f=e.target.elements;state.settings={goal:+f.namedItem('goal').value,size:'all',direction:'fi-en',strict:f.namedItem('strict').checked};save();toast('Your preferences are saved.');render()};if($('#addWord'))$('#addWord').onclick=()=>editWord();$('#backup').onclick=()=>download(JSON.stringify({type:'sisu-backup',version:1,createdAt:new Date().toISOString(),state},null,2),'sisu-backup-'+day()+'.json','application/json');$('#restore').onclick=()=>$('#backupInput').click();$('#importLegacy').onclick=importLegacyProgress;$('#backupInput').onchange=e=>{const file=e.target.files[0];e.target.value='';restoreBackup(file)};if($('#importWords'))$('#importWords').onclick=()=>$('#fileInput').click();$('#fileInput').onchange=e=>{const file=e.target.files[0];e.target.value='';importFile(file)};$('#downloadJSON').onclick=()=>download(JSON.stringify({schemaVersion:1,chapters:SEED.chapters,sections:SEED.sections,entries:entries()},null,2),'sisu-vocabulary.json','application/json');$('#downloadCSV').onclick=()=>download(toCSV(entries()),'sisu-vocabulary.csv','text/csv;charset=utf-8');if($('#templateCSV'))$('#templateCSV').onclick=()=>download('fi,en,pos,book,chapter,section,spoken,notes\noppia,to learn,V1,1,1,My extra words,false,\n','sisu-import-template.csv','text/csv');$('#voiceTest').onclick=()=>speak('Hei! On hauska oppia suomea.');$('#resetProgress').onclick=()=>confirmDialog('Reset learning progress?','This clears your recall progress and practice history. Vocabulary, edits and stars will stay.',()=>{state.progress={};state.history={};save();render();toast('Learning progress reset.')})}
function download(text,name,type){const url=URL.createObjectURL(new Blob([type.startsWith('text/csv')?'\uFEFF'+text:text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function toCSV(arr){const fields=['fi','en','pos','book','chapter','section','spoken','notes'];return fields.join(',')+'\r\n'+arr.map(e=>fields.map(k=>'"'+String(k==='chapter'?chapter(e.chapter)?.number||'':k==='section'?section(e.section)?.title||e.section||'':e[k]??'').replace(/"/g,'""')+'"').join(',')).join('\r\n')}
function sourceInformation(e){
 if(!e.sourcePlacement)return '';
 const c=chapter(e.chapter);
 let detail=e.sourcePlacement==='located'?`Located in Suomen Mestari ${e.book}, Chapter ${c?.number}, printed page ${e.sourcePage}.`:
 e.sourcePlacement==='related-form'?`A related or inflected book form is on printed page ${e.sourcePage}: “${e.sourceForm}”. The supplied vocabulary wording is retained.`:
 `Placed in Chapter ${c?.number} by meaning. This wording has not been located in the supplied scans; no book page is claimed.`;
 return `<details class="source-details"><summary>Source information</summary><p>${esc(detail)}</p></details>`;
}
function editWord(id){if(!canEditVocabulary()){toast('Only Sawyer can change vocabulary.');return}let original=entries().find(e=>e.id===id),e=original||{fi:'',en:'',pos:'N',book:bookFilter==='2'?2:1,chapter:null,section:'',notes:'',spoken:false};let m=$('#modal');m.innerHTML=`<h2>${id?'Edit a word':'A new word to learn.'}</h2>${sourceInformation(e)}<form id="wordForm"><div class="formgrid"><label>Finnish<input name="fi" value="${esc(e.fi)}" required maxlength="300"></label><label>English<input name="en" value="${esc(e.en)}" required maxlength="1000"></label><label>Part of speech<select name="pos" multiple size="5" aria-label="Parts of speech; select all that apply">${['N','V1','V2','V3','V4','V5','V6','A','AV','PR','PN','PH','NU','IN','CO','PO','PE','Q','PA'].map(p=>`<option value="${p}" ${e.pos.split('+').includes(p)?'selected':''}>${esc(posLabel(p))}</option>`).join('')}</select></label><label>Book<select name="book"><option value="1" ${e.book===1?'selected':''}>Suomen Mestari 1</option><option value="2" ${e.book===2?'selected':''}>Suomen Mestari 2</option></select></label><label class="full">Source chapter (optional)<select name="chapter"><option value="">Not assigned</option>${SEED.chapters.map(c=>`<option value="${c.id}" ${e.chapter===c.id?'selected':''}>SM${c.book} · ${c.number}. ${esc(titleFi(c.title))}</option>`).join('')}</select></label><label class="full">Topic / section<select name="section"><option value="">Personal vocabulary</option>${SEED.sections.filter(s=>!s.archived).map(s=>`<option value="${s.id}" ${e.section===s.id?'selected':''}>${'SM'+s.book+(s.chapter?' · '+chapter(s.chapter)?.number:' · Topic')} · ${esc(s.title)}</option>`).join('')}</select></label><label class="full">Your notes<textarea name="notes" maxlength="2000">${esc(e.notes)}</textarea></label><label class="check full"><input type="checkbox" name="spoken" ${e.spoken?'checked':''}> Spoken Finnish</label></div><div class="actions">${id?'<button type="button" id="deleteWord" class="danger">Remove</button>':''}<button type="button" id="cancelEdit">Cancel</button><button class="primary">Save word</button></div></form>`;$('#cancelEdit').onclick=()=>m.close();let f=$('#wordForm'),el=n=>f.elements.namedItem(n);el('chapter').onchange=()=>{if(el('chapter').value)el('book').value=chapter(el('chapter').value).book;el('section').value=''};el('section').onchange=()=>{let sec=section(el('section').value);if(sec){if(sec.book)el('book').value=sec.book;el('chapter').value=sec.chapter||''}};el('book').onchange=()=>{if(chapter(el('chapter').value)?.book!==+el('book').value){el('chapter').value='';el('section').value=''}};const updateWordTopics=(selected)=>{const previousChapter=el('chapter').value;el('chapter').innerHTML='<option value="">Not assigned</option>'+SEED.chapters.filter(c=>c.book===+el('book').value).map(c=>`<option value="${c.id}">${c.number}. ${esc(titleFi(c.title))}</option>`).join('');el('chapter').value=SEED.chapters.some(c=>c.id===previousChapter&&c.book===+el('book').value)?previousChapter:'';el('section').innerHTML=SEED.sections.filter(t=>!t.archived&&t.book===+el('book').value&&(!el('chapter').value||t.chapter===el('chapter').value)).map(t=>`<option value="${t.id}">${esc(t.title)}${t.chapter?' · Chapter '+chapter(t.chapter)?.number:''}</option>`).join('');el('section').value=bookTopicId(selected,+el('book').value);if(!el('section').value)el('section').selectedIndex=0};updateWordTopics(e.section);el('book').onchange=()=>{el('chapter').value='';updateWordTopics(null)};el('section').onchange=()=>{const t=section(el('section').value);if(t?.chapter)el('chapter').value=t.chapter};el('chapter').onchange=()=>{if(el('chapter').value)el('book').value=chapter(el('chapter').value).book;updateWordTopics(el('section').value)};f.onsubmit=ev=>{ev.preventDefault();let fi=el('fi').value.trim(),en=el('en').value.trim();if(!fi||!en){toast('Both Finnish and English are required.');return}let updated={...e,id:id||'custom-'+crypto.randomUUID(),fi,en,pos:Array.from(el('pos').selectedOptions).map(o=>o.value).join('+')||'N',book:+el('book').value,chapter:el('chapter').value||null,section:bookTopicId(el('section').value,+el('book').value),spoken:el('spoken').checked,notes:el('notes').value.trim(),placement:'user-reviewed'};if(original&&(en!==original.en||updated.pos!==original.pos)){delete updated.senses;}if(original&&(fi!==original.fi||updated.chapter!==original.chapter||updated.book!==original.book)){delete updated.sourcePage;delete updated.sourceForm;delete updated.sourcePlacement;}if(id&&SEED.entries.some(x=>x.id===id))state.overrides[id]=updated;else if(id)state.custom=state.custom.map(x=>x.id===id?updated:x);else state.custom.push(updated);if(original&&key(original)!==key(updated)&&state.progress[key(original)]&&!state.progress[key(updated)])state.progress[key(updated)]={...state.progress[key(original)]};save();m.close();render();toast('Word saved.')};if($('#deleteWord'))$('#deleteWord').onclick=()=>{m.close();confirmDialog('Remove this word?',`Remove “${e.fi}” from your vocabulary? A backup can restore it.`,()=>{if(SEED.entries.some(x=>x.id===id))state.hidden.push(id);else state.custom=state.custom.filter(x=>x.id!==id);save();render();toast('Word removed.')})};m.showModal()}
function parseCSV(text){let rows=[],row=[],val='',quoted=false;text=text.replace(/^\uFEFF/,'');for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){val+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(val);val=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(val);if(row.some(x=>x.trim()))rows.push(row);row=[];val=''}else val+=c}if(quoted)throw Error('Unclosed quotation mark in CSV.');row.push(val);if(row.some(x=>x.trim()))rows.push(row);if(!rows.length)throw Error('The file is empty.');let heads=rows.shift().map(x=>x.trim().toLowerCase());if(!heads.includes('fi')||!heads.includes('en'))throw Error('CSV needs fi and en column headers.');return rows.map(r=>Object.fromEntries(heads.map((h,i)=>[h,r[i]||''])))}
async function importFile(file){if(!canEditVocabulary()){toast('Only Sawyer can import vocabulary.');return}if(!file)return;if(file.size>10000000){toast('Please use a file smaller than 10 MB.');return}try{let text=await file.text(),raw=file.name.toLowerCase().endsWith('.json')?JSON.parse(text):parseCSV(text);let source=Array.isArray(raw)?raw:raw.entries;if(!Array.isArray(source))throw Error('JSON must contain an entries array.');if(source.length>15000)throw Error('Import up to 15,000 words at a time.');let valid=[],invalid=0;for(let e of source){if(!e||typeof e.fi!=='string'||typeof e.en!=='string'||!e.fi.trim()||!e.en.trim()){invalid++;continue}let b=+e.book===2?2:1,c=chapter(e.chapter)||SEED.chapters.find(x=>x.book===b&&x.number===+e.chapter),sec=section(e.section)||SEED.sections.find(x=>(x.book===(c?.book||b)||!x.book)&&(!c||x.chapter===c.id)&&x.title===e.section)||SEED.sections.find(x=>!x.archived&&x.title===e.section);valid.push({id:'custom-'+crypto.randomUUID(),fi:e.fi.trim().slice(0,300),en:e.en.trim().slice(0,1000),pos:String(e.pos||'').slice(0,10),book:c?.book||b,chapter:c?.id||null,section:bookTopicId(sec?.id,c?.book||b),spoken:e.spoken===true||String(e.spoken).toLowerCase()==='true',notes:String(e.notes||'').slice(0,2000),placement:'user-imported'})}let existing=new Set(entries().map(e=>`${key(e)}|${e.chapter}`)),fresh=valid.filter(e=>{let k=`${key(e)}|${e.chapter}`;if(existing.has(k))return false;existing.add(k);return true}),dup=valid.length-fresh.length;let m=$('#modal');m.innerHTML=`<h2>Here’s what will come in.</h2><p>${fresh.length} new ${fresh.length===1?'entry':'entries'} · ${dup} ${dup===1?'duplicate':'duplicates'} skipped · ${invalid} invalid ${invalid===1?'row':'rows'} skipped</p><div class="notice">Words without a source chapter stay in their book’s topics. This import adds vocabulary; it does not overwrite your existing words or progress.</div><div style="max-height:240px;overflow:auto">${fresh.slice(0,30).map(e=>`<p style="font-size:13px"><strong>${esc(e.fi)}</strong> — ${esc(e.en)}<br><small>${e.chapter?'SM'+e.book+' · Chapter '+chapter(e.chapter).number:'SM'+e.book+' · Topic'}</small></p>`).join('')}${fresh.length>30?'<small>And '+(fresh.length-30)+' more…</small>':''}</div><div class="actions"><button id="cancelImport">Cancel</button><button id="confirmImport" class="primary" ${fresh.length?'':'disabled'}>Add ${fresh.length} ${fresh.length===1?'entry':'entries'}</button></div>`;$('#cancelImport').onclick=()=>m.close();$('#confirmImport').onclick=()=>{state.custom.push(...fresh);save();m.close();render();toast(`${fresh.length} words added.`)};m.showModal()}catch(e){toast('Import could not be read: '+e.message)}}
function validBackup(s){return s&&typeof s==='object'&&!Array.isArray(s)&&s.schemaVersion===1&&s.progress&&typeof s.progress==='object'&&!Array.isArray(s.progress)&&Array.isArray(s.custom)&&s.custom.every(e=>e&&typeof e.id==='string'&&typeof e.fi==='string'&&typeof e.en==='string')&&Array.isArray(s.stars)&&Array.isArray(s.hidden)&&s.overrides&&typeof s.overrides==='object'&&Object.values(s.overrides).every(e=>e&&typeof e.fi==='string'&&typeof e.en==='string')&&s.history&&typeof s.history==='object'&&s.settings&&Number.isFinite(+s.settings.goal)&&+s.settings.goal>0}
async function restoreBackup(file){if(!account.user){openAccount();return}if(!file)return;try{if(file.size>20000000)throw Error('Backup file is too large.');let b=JSON.parse(await file.text());if(b.type!=='sisu-backup'||b.version!==1||!validBackup(b.state))throw Error('This is not a supported Sisu backup.');confirmDialog('Restore this backup?',`This replaces your current local vocabulary edits, settings and progress with the backup from ${new Date(b.createdAt).toLocaleDateString('en-US')}. Download your current backup first if you need to keep it.`,()=>{state=restoredAccountState(b.state);applyCategoryRevision();save();view='home';render();toast('Backup restored.')})}catch(e){toast('Could not restore: '+e.message)}}
document.addEventListener('keydown',ev=>{
 if(view!=='session'||!session||session.complete||$('#modal').open||ev.repeat||['INPUT','TEXTAREA','SELECT'].includes(ev.target.tagName))return;
 const s=session;
 if(s.mode==='flash'){
  if(ev.key==='ArrowRight'){ev.preventDefault();skipFlash()}
  else if(s.revealed&&['1','2'].includes(ev.key)){ev.preventDefault();rateFlash(+ev.key-1)}
  else if(ev.code==='Space'&&ev.target.tagName!=='BUTTON'){ev.preventDefault();flip()}
  return;
 }
 if(ev.target.tagName==='BUTTON')return;
 if(s.mode==='learn'&&!s.feedback&&['1','2','3','4'].includes(ev.key)&&s.options?.[+ev.key-1])submitAnswer(s.options[+ev.key-1]);else if(s.feedback&&ev.key==='Enter')nextQuestion();
});
function updateAccountUI(){
 $$('[data-account]').forEach(b=>{b.textContent=account.user?account.user.username:account.ready?'Sign in':'Loading…';b.disabled=!account.ready});
 const labels={guest:'',saving:'Saving…',saved:'Saved',error:'Save failed',conflict:'Sync conflict'};
 $$('[data-sync]').forEach(e=>{e.textContent=account.user?(labels[account.status]||''):'';e.classList.toggle('sync-error',['error','conflict'].includes(account.status))});
}
const ACCOUNT_HOST=typeof location!=='undefined'&&location.origin==='https://sawyer-des.github.io'?'https://sisu-finnish-vocabulary.sawyerperry905.chatgpt.site':'';
const SESSION_KEY='sisu-account-session';
let pagesSession='';if(ACCOUNT_HOST)try{pagesSession=localStorage.getItem(SESSION_KEY)||''}catch{}
async function accountAPI(path,method='GET',body){
 const response=await fetch(ACCOUNT_HOST+path,{method,credentials:ACCOUNT_HOST?'omit':'same-origin',cache:'no-store',headers:{...(body?{'Content-Type':'application/json'}:{}),...(ACCOUNT_HOST&&pagesSession?{Authorization:'Bearer '+pagesSession}:{})},...(body?{body:JSON.stringify(body)}:{})});
 let data;try{data=await response.json()}catch{throw Error('Accounts are unavailable on this host. Use the server-backed Sisu site.')}
 if(!response.ok)throw Object.assign(Error(data.error||'The account request failed.'),{status:response.status});if(ACCOUNT_HOST&&data.sessionToken){pagesSession=data.sessionToken;try{localStorage.setItem(SESSION_KEY,pagesSession)}catch{}}if(ACCOUNT_HOST&&(path==='/api/logout'||path==='/api/session'&&!data.user)){pagesSession='';try{localStorage.removeItem(SESSION_KEY)}catch{}}return data;
}
function installAccount(data){
 accountEpoch++;state={...freshState(),...(data.state||{})};state.settings={...freshState().settings,...state.settings,direction:'fi-en',size:'all'};
 applyCategoryRevision();account={user:data.user,revision:data.revision||0,ready:true,status:'saved',dirty:false,conflict:false};session=null;view='home';render();
}
async function loadAccount(){
 try{const data=await accountAPI('/api/session');if(data.user)installAccount(data);else{account.ready=true;render()}}
 catch{account.ready=true;account.unavailable=true;render()}
}
async function flushAccountSave(){
 clearTimeout(accountSaveTimer);
 if(pendingAccountSave){const ok=await pendingAccountSave;if(ok&&account.dirty&&!account.conflict)return flushAccountSave();return ok&&!account.dirty}
 if(!account.user||!account.dirty)return true;if(account.conflict)return false;
 const epoch=accountEpoch,userId=account.user.id,revision=account.revision,snapshot=JSON.parse(JSON.stringify(state));account.dirty=false;
 pendingAccountSave=(async()=>{
  try{const data=await accountAPI('/api/state','PUT',{accountId:userId,revision,state:snapshot});if(epoch!==accountEpoch)return false;account.revision=data.revision;account.status=account.dirty?'saving':'saved';return true}
  catch(error){if(epoch!==accountEpoch)return false;account.dirty=true;account.status=error.status===409?'conflict':'error';account.conflict=error.status===409;toast(error.message);return false}
  finally{if(epoch===accountEpoch)updateAccountUI()}
 })();
 const ok=await pendingAccountSave;pendingAccountSave=null;if(ok&&account.dirty)return flushAccountSave();return ok;
}
function guestAccountPage(title){shell(`${heading('YOUR OWN LEARNING SPACE',title,'Create an account with only a username and password. No email required.')}<section class="panel account-welcome"><h2>Keep your learning yours.</h2><p class="muted">Guest practice saves no progress. Sign in to track your words, stars and practice history separately from everyone else.</p><button class="primary" data-account>Sign in or create account</button></section>`)}
function openAccount(mode='login'){
 const m=$('#modal');if(!account.ready)return;
 if(account.user){
  m.innerHTML=`<h2>${esc(account.user.username)}</h2><p class="muted">Your progress belongs to this account.</p><p>${account.status!=='saved'?'Some changes have not been saved yet.':'Your progress is saved to your account.'}</p><div class="actions">${account.dirty?'<button id="retrySync">Retry save</button><button id="unsavedBackup">Download backup</button>':''}<button id="closeAccount">Close</button><button id="signOut">Sign out</button></div>`;
  $('#closeAccount').onclick=()=>m.close();if($('#retrySync'))$('#retrySync').onclick=async()=>{if(account.conflict){toast('Download a backup before reloading this tab to resolve the sync conflict.');return}await flushAccountSave();openAccount()};
  if($('#unsavedBackup'))$('#unsavedBackup').onclick=()=>download(JSON.stringify({type:'sisu-backup',version:1,createdAt:new Date().toISOString(),state},null,2),'sisu-backup-'+day()+'.json','application/json');
  $('#signOut').onclick=async()=>{const b=$('#signOut');b.disabled=true;try{if(!await flushAccountSave())throw Error('Your latest changes are not saved. Download a backup or retry before signing out.');await accountAPI('/api/logout','POST',{accountId:account.user.id});accountEpoch++;account={user:null,ready:true,revision:0,status:'guest',dirty:false,conflict:false};state=freshState();session=null;view='home';m.close();render()}catch(e){toast(e.message);b.disabled=false}};m.showModal();return;
 }
 const register=mode==='register';
 m.innerHTML=`<h2>${register?'Create your Sisu account':'Welcome back.'}</h2><p class="muted">${register?'Just a username and password. No email, no profile details.':'Sign in to continue with your own progress.'}</p><form id="accountForm"><div class="formgrid"><label class="full">Username<input name="username" autocomplete="username" autocapitalize="none" spellcheck="false" required minlength="3" maxlength="32" pattern="[A-Za-z0-9][A-Za-z0-9_.-]{1,30}[A-Za-z0-9]"></label><label class="full">Password<input name="password" type="password" autocomplete="${register?'new-password':'current-password'}" required ${register?'minlength="15"':''} maxlength="128"></label></div>${register?'<p class="sourceinfo">Use 15–128 characters. Keep your password safe: there is no email-based password recovery.</p>':''}<p id="accountError" class="account-error" role="alert"></p><div class="actions"><button type="button" id="cancelAccount">Cancel</button><button class="primary" id="submitAccount">${register?'Create account':'Sign in'}</button></div></form><button id="switchAccountMode" class="ghost">${register?'Already have an account? Sign in':'New here? Create an account'}</button>`;
 $('#cancelAccount').onclick=()=>m.close();$('#switchAccountMode').onclick=()=>openAccount(register?'login':'register');
 $('#accountForm').onsubmit=async event=>{event.preventDefault();const form=event.target,b=$('#submitAccount');b.disabled=true;$('#accountError').textContent='';
  try{if(pendingAccountSave)await pendingAccountSave;const data=await accountAPI(register?'/api/register':'/api/login','POST',{username:form.elements.namedItem('username').value,password:form.elements.namedItem('password').value});form.reset();m.close();installAccount(data);toast('Signed in as '+data.user.username)}catch(error){$('#accountError').textContent=error.message;b.disabled=false}
 };m.showModal();
}
function importLegacyProgress(){
 if(!account.user)return;let previous;try{previous=JSON.parse(localStorage.getItem(LEGACY_KEY)||'null')}catch{}
 if(!validBackup(previous)){toast('No previous device progress was found. You can still restore a downloaded backup.');return}
 confirmDialog('Import previous device progress?',`Replace ${account.user.username}’s current collection and progress with the old data saved on this browser? Download a backup first if you want to keep both.`,()=>{state=restoredAccountState(previous);state.settings={...freshState().settings,...state.settings,direction:'fi-en',size:'all'};applyCategoryRevision();save();render();toast('Previous device progress imported into your account.')});
}
if(typeof window.addEventListener==='function'){
 window.addEventListener('online',()=>{if(account.user&&account.dirty&&!account.conflict)flushAccountSave()});
 window.addEventListener('beforeunload',event=>{if(account.user&&(account.dirty||pendingAccountSave)){event.preventDefault();event.returnValue=''}});
}

render();
if(typeof fetch==='function'&&typeof location!=='undefined')loadAccount();else{account.ready=true}

let lastReleaseCheck=0;
async function checkForAppUpdate(){
 if(location.protocol==='file:'||!document.querySelector('meta[name="sisu-build"]')||Date.now()-lastReleaseCheck<60000)return;
 lastReleaseCheck=Date.now();
 try{
  const response=await fetch('release.json',{cache:'no-store'});if(!response.ok)return;
  const release=await response.json(),current=document.querySelector('meta[name="sisu-build"]').content;
  if(!release.version||release.version===current||document.querySelector('#updateNotice'))return;
  const notice=document.createElement('aside');notice.id='updateNotice';notice.setAttribute('role','status');notice.innerHTML='<span>A new version of Sisu is ready.</span><button>Reload update</button>';
  notice.querySelector('button').onclick=()=>{const reload=()=>{const url=new URL(location.href);url.searchParams.set('v',release.version);location.replace(url.href)};if(session&&view==='session')confirmDialog('Load the update?','Completed answers are saved. Finish your current question first if you want it saved too.',reload);else reload()};
  document.body.append(notice);
 }catch{}
}
if(typeof location!=='undefined'){
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkForAppUpdate()});checkForAppUpdate();
}
